@Override
public FileVisitResult visitFile(Path file, BasicFileAttributes attributes) {
	if (filter.test(file)) {
		consumer.accept(basePath, file);
	}
	return CONTINUE;
}

private static void walkFilesForUri(URI baseUri, Predicate<Path> filter, BiConsumer<Path, Path> consumer) {
	try (CloseablePath closeablePath = CloseablePath.create(baseUri)) {
		Path baseDir = closeablePath.getPath();
		Preconditions.condition(Files.exists(baseDir), () -> "baseDir must exist: " + baseDir);
		try {
			Files.walkFileTree(baseDir, new ClasspathFileVisitor(baseDir, filter, consumer));
		}
		catch (IOException ex) {
			logger.warn(ex, () -> "I/O error scanning files in " + baseDir);
		}
	}
	catch (PreconditionViolationException ex) {
		throw ex;
	}
	catch (Exception ex) {
		logger.warn(ex, () -> "Error scanning files for URI " + baseUri);

private void processClassFileSafely(Path baseDir, String basePackageName, ClassFilter classFilter, Path file,
		Consumer<Class<?>> classConsumer) {
	try {
		String fullyQualifiedClassName = determineFullyQualifiedClassName(baseDir, basePackageName, file);
		if (classFilter.match(fullyQualifiedClassName)) {
			try {
				// @formatter:off
				loadClass.apply(fullyQualifiedClassName, getClassLoader())
						.toOptional()
						.filter(classFilter::match)
						.ifPresent(classConsumer);
				// @formatter:on
			}
			catch (InternalError internalError) {
				handleInternalError(file, fullyQualifiedClassName, internalError);
			}

private void processResourceFileSafely(Path baseDir, String basePackageName, ResourceFilter resourceFilter,
		Path resourceFile, Consumer<Resource> resourceConsumer) {
	try {
		String fullyQualifiedResourceName = determineFullyQualifiedResourceName(baseDir, basePackageName,
			resourceFile);
		Resource resource = Resource.of(fullyQualifiedResourceName, resourceFile.toUri());
		if (resourceFilter.match(resource)) {
			resourceConsumer.accept(resource);
		}
		// @formatter:on
	}
	catch (Throwable throwable) {
		handleThrowable(resourceFile, throwable);
	}
}

static boolean isClassOrSourceFile(Path file) {
	var fileName = file.getFileName().toString();
	return isClassOrSourceFile(fileName) && !isModuleInfoOrPackageInfo(fileName);
}

private String determineFullyQualifiedResourceName(Path baseDir, String basePackageName, Path resourceFile) {
	// @formatter:off
	return Stream.of(
				packagePath(basePackageName),
				packagePath(determineSubpackageName(baseDir, resourceFile)),
				determineSimpleResourceName(resourceFile)
			)
			.filter(value -> !value.isEmpty()) // Handle default package appropriately.
			.collect(joining(CLASSPATH_RESOURCE_PATH_SEPARATOR_STRING));
	// @formatter:on
}

public static Path findPath(Path rootDir, String syntaxAndPattern) {
	var matcher = rootDir.getFileSystem().getPathMatcher(syntaxAndPattern);
	try (var files = Files.walk(rootDir)) {
		return files.filter(matcher::matches).findFirst() //
				.orElseThrow(() -> new AssertionError(
					"Failed to find file matching '%s' in %s".formatted(syntaxAndPattern, rootDir)));
	}
	catch (IOException e) {
		throw new UncheckedIOException(e);
	}
}

@API(status = MAINTAINED, since = "1.14")
@SuppressWarnings("removal")
default List<? extends Resource> scanForResourcesInClasspathRoot(URI root, ResourceFilter resourceFilter) {
	return scanForResourcesInClasspathRoot(root, resourceFilter::match);
}

@Override
public InputStream openClasspathResource(Class<?> baseClass, String path) {
	Preconditions.notBlank(path, () -> "Classpath resource [" + path + "] must not be null or blank");
	//noinspection resource (closed elsewhere)
	InputStream inputStream = baseClass.getResourceAsStream(path);
	return Preconditions.notNull(inputStream, () -> "Classpath resource [" + path + "] does not exist");
}

ClasspathFileVisitor(Path basePath, Predicate<Path> filter, BiConsumer<Path, Path> consumer) {
	this.basePath = basePath;
	this.filter = filter;
	this.consumer = consumer;
}
